#!/usr/bin/env node
// Supporting measurement for F2: the CubeCorners tip error is geometric, not
// a cable-stiffness artefact.  Replays the cached 5 mm +X layered CubeCorners
// capture (generated by kinematics_e2e.mjs) at four scene stiffnesses.
//
//   node kinematics_e2e.mjs --machines=cubecorners_w_line_layers --move=5 --axes=X --out=/tmp/x.json
//   node probe_cube_stiffness.mjs 2000
//   node probe_cube_stiffness.mjs 20000
//   node probe_cube_stiffness.mjs 100000
//
// Observed: 2000 -> 4.6044 mm, 10000 -> 4.7468, 20000 -> 4.7347,
// 100000 -> 4.7347.  The geometric limit is 4.7346 mm.
import fs from 'node:fs'; import path from 'node:path';
const ROOT='/home/torbjorn/repos/hp-sim5'; let collected=[];
globalThis.self={addEventListener(){},onmessage:null,postMessage(){},console};
globalThis.postMessage=(m)=>{const c=m?.command??m; if(c&&c.type==='Move')collected.push(c);};
const {RrfCanPlayer}=await import(path.join(ROOT,'integrations/rrf/rrfCanPlayer.js'));
const {FileFormat}=await import(path.join(ROOT,'integrations/shared/fileFormatUtils.js'));
const {createHeadlessWorld}=await import(path.join(ROOT,'hp-sim-3d/app/headlessWorld.js'));
const ecs=await import(path.join(ROOT,'src/js/cable_joints_3d/ecs.js'));
const {ExtruderComponent}=await import(path.join(ROOT,'hp-sim-3d/app/hangprinter_extruder.js'));
const Vector3=(await import(path.join(ROOT,'src/js/cable_joints_3d/vector3.js'))).default;
const cap=JSON.parse(fs.readFileSync('/tmp/opencode/kin-e2e/config_cubecorners_w_line_layers.g_X_5.json','utf8'));
const p=new RrfCanPlayer();p.asapMode=true;p.asapYieldBudgetMs=1e9;
await p.run(new ReadableStream({start(c){c.enqueue(new TextEncoder().encode(cap.csvText));c.close();}}),FileFormat.RRF_CAN);
let scene=fs.readFileSync(path.join(ROOT,'public/usd_scenes/cubecorners.usda'),'utf8');
const stiff=Number(process.argv[2]||20000);
scene=scene.replaceAll('cablePath:stiffnessPerUnitLength = 20000.0','cablePath:stiffnessPerUnitLength = '+stiff+'.0');
const {world,remote,dt}=createHeadlessWorld(scene,{lineLayeringEnabled:true});
world.setResource('gravity',new Vector3());
const body=world.query([ecs.RigidBodyComponent])[0]; const ex=world.query([ExtruderComponent])[0];
for(let i=0;i<5000;i++)world.update(dt);
const tp=()=>{const t=world.getComponent(ex,ExtruderComponent).tipPos;return [t.x*1000,t.y*1000,t.z*1000];};
const t0=tp();
for(const c of collected){remote.commands=[c];world.update(dt);}
for(let i=0;i<15000;i++)world.update(dt);
const t1=tp();
console.log('stiffness',stiff,'tip delta',t1.map((v,i)=>(v-t0[i]).toFixed(4)));
